export function getProductsByCategory(slug: string): Product[] {
    return products.filter((p) => p.categorySlug === slug);
}

export function getProductsByIndustry(slug: string): Product[] {
    return products.filter((p) => p.industries.some((i) => i.slug === slug));
}

